#ifndef SIMHASH_PERMUTATION_H
#define SIMHASH_PERMUTATION_H

#include "simhash.h"

#include <vector>

namespace Simhash {

    class Permutation {
    public:
        /**
         * Create a vector of permutations necessary to do all simhash near-dup
         * detection.
         */
        static std::vector<Permutation> create(size_t number_of_blocks,
                                               size_t different_bits);

        /**
         * Generate combinations of length r from population.
         */
        static std::vector<std::vector<hash_t> > choose(
            const std::vector<hash_t>& population, size_t r);

        /**
         * Construct a permutation from its permutation masks and the maximum
         * number of bits that may differ.
         */
        Permutation(size_t different_bits, std::vector<hash_t>& masks);

        /**
         * Apply this permutation.
         */
        hash_t apply(hash_t hash) const;

        /**
         * Reverse this permutation, getting the original.
         */
        hash_t reverse(hash_t hash) const;

        /**
         * Search mask
         *
         * When searching for a potential match, a match may be less than
         * the query, so it's insufficient to simply search for the query.
         * This mask sets all the bits in the last _differing_bits_ blocks
         * to 0, which is smaller than is necessary, but the easiest correct
         * number to compute. The highest number which must be potentially
         * searched is the query with all the bits in the last
         * _differing_bits_ blocks set to 1. */
        hash_t search_mask() const;
    private:
        std::vector<hash_t> forward_masks;
        std::vector<hash_t> reverse_masks;
        std::vector<int> offsets;
        hash_t search_mask_;
    };
}

#endif

#ifndef SIMHASH_SIMHASH_H
#define SIMHASH_SIMHASH_H

#include <cstddef>
#include <stdint.h>
#include <unordered_set>
#include <utility>
#include <vector>

namespace Simhash {

    /**
     * The type of all hashes.
     */
    typedef uint64_t hash_t;

    /**
     * The type of a match of two hashes.
     */
    typedef std::pair<hash_t, hash_t> match_t;

    /**
     * For use with matches_t.
     */
    struct match_t_hash {
        inline std::size_t operator()(const std::pair<hash_t,hash_t>& v) const {
            return static_cast<hash_t>(v.first * 31 + v.second);
        }
    };

    /**
     * The type for matches what we've returned.
     */
    typedef std::unordered_set<match_t, match_t_hash> matches_t;

    /**
     * The number of bits in a hash_t.
     */
    static const size_t BITS = sizeof(hash_t) * 8;

    /**
     * Compute the number of bits that are flipped between two numbers
     *
     * @param a - reference number
     * @param b - number to compare
     *
     * @return number of bits that differ between a and b */
    size_t num_differing_bits(hash_t a, hash_t b);

    /**
     * Compute the simhash of a vector of hashes.
     */
    hash_t compute(const std::vector<hash_t>& hashes);

    /**
     * Find the set of all matches within the provided vector of hashes.
     *
     * The provided hashes are manipulated in place, but upon completion are
     * restored to their original state.
     */
    matches_t find_all(std::unordered_set<hash_t>& hashes,
                       size_t number_of_blocks,
                       size_t different_bits);
}

#endif

#include <iostream>
#include <unordered_set>
#include <sstream>
#include <fstream>

#include <getopt.h>

#include "simhash.h"

void usage(int argc, char** argv)
{
    std::cout << "usage: " << argv[0]
              << " --blocks BLOCKS"
              << " --distance DISTANCE"
              << " --input INPUT"
              << " --output OUTPUT\n\n"
              << "Read simhashes from input, find all pairs within distance bits of \n"
              << "each other, writing them to output. The endianness of the output is \n"
              << "the same as that of the input.\n\n"
              << "  --blocks BLOCKS        Number of bit blocks to use\n"
              << "  --distance DISTANCE    Maximum bit distances of matches\n"
              << "  --input INPUT          Path to input ('-' for stdin)\n"
              << "  --output OUTPUT        Path to output ('-' for stdout)\n";
}

std::unordered_set<Simhash::hash_t> read_hashes(std::istream& stream)
{
    std::unordered_set<Simhash::hash_t> hashes;
    Simhash::hash_t hash(0);
    while (!stream.eof())
    {
        stream.read(reinterpret_cast<char*>(&hash), sizeof(hash));
        if (!stream.fail())
        {
            hashes.insert(hash);
        }
        else
        {
            break;
        }
    }
    return hashes;
}

void write_matches(std::ostream& stream, const Simhash::matches_t& matches)
{
    for (auto it = matches.begin(); it != matches.end() && !std::cout.fail(); ++it)
    {
        stream.write(
            reinterpret_cast<const char*>(&(it->first)), sizeof(Simhash::hash_t));
        stream.write(
            reinterpret_cast<const char*>(&(it->second)), sizeof(Simhash::hash_t));
    }
    stream.flush();
}

int main(int argc, char **argv) {

    std::string input, output;
    size_t blocks(0), distance(0);

    int getopt_return_value(0);
    while (getopt_return_value != -1)
    {
        int option_index = 0;
        static struct option long_options[] = {
            {"input",    required_argument, 0, 0 },
            {"output",   required_argument, 0, 0 },
            {"blocks",   required_argument, 0, 0 },
            {"distance", required_argument, 0, 0 },
            {"help",     no_argument,       0, 0 },
            {0,          0,                 0, 0 }
        };

        getopt_return_value = getopt_long(
            argc, argv, "i:o:b:d:h", long_options, &option_index);

        switch(getopt_return_value)
        {
            case 0:
                switch(option_index)
                {
                    case 0:
                        input = optarg;
                        break;
                    case 1:
                        output = optarg;
                        break;
                    case 2:
                        std::stringstream(std::string(optarg)) >> blocks;
                        break;
                    case 3:
                        std::stringstream(std::string(optarg)) >> distance;
                        break;
                    case 4:
                        usage(argc, argv);
                        return 0;
                }
                break;
            case 'i':
                input = optarg;
                break;
            case 'o':
                output = optarg;
                break;
            case 'b':
                std::stringstream(std::string(optarg)) >> blocks;
                break;
            case 'd':
                std::stringstream(std::string(optarg)) >> distance;
                break;
            case 'h':
                usage(argc, argv);
                return 0;
            case '?':
                return 1;
        }

    }

    if (blocks == 0)
    {
        std::cerr << "Blocks must be provided and > 0" << std::endl;
        return 2;
    }

    if (distance == 0)
    {
        std::cerr << "Distance must be provided and > 0" << std::endl;
        return 3;
    }

    if (input.empty())
    {
        std::cerr << "Input must be provided and non-empty." << std::endl;
        return 4;
    }

    if (output.empty())
    {
        std::cerr << "Output must be provided and non-empty." << std::endl;
        return 5;
    }

    if (blocks <= distance)
    {
        std::cerr << "Blocks (" << blocks << ") must be >= distance (" << distance << ")"
                  << std::endl;
        return 6;
    }

    // Read input
    std::unordered_set<Simhash::hash_t> hashes;
    if (input.compare("-") == 0)
    {
        std::cerr << "Reading hashes from stdin." << std::endl;
        hashes = read_hashes(std::cin);
    }
    else
    {
        std::cerr << "Reading hashes from " << input << std::endl;
        {
            std::ifstream fin(input, std::ifstream::in | std::ifstream::binary);
            if (!fin.good())
            {
                std::cerr << "Error reading " << input << std::endl;
                return 7;
            }
            hashes = read_hashes(fin);
        }
    }

    // Find matches
    std::cerr << "Computing matches..." << std::endl;
    Simhash::matches_t results = Simhash::find_all(hashes, blocks, distance);

    // Write output
    if (output.compare("-") == 0)
    {
        std::cerr << "Writing results to stdout." << std::endl;
        write_matches(std::cout, results);
    }
    else
    {
        std::cerr << "Writing matches to " << output << std::endl;
        {
            std::ofstream fout(output, std::ofstream::binary);
            if (!fout.good())
            {
                std::cerr << "Error writing " << output << std::endl;
                return 8;
            }
            write_matches(fout, results);
        }
    }

    return 0;
}

#include "permutation.h"

#include <algorithm>
#include <sstream>
#include <stdexcept>
#include <vector>

namespace Simhash {

    std::vector<std::vector<hash_t> > Permutation::choose(
            const std::vector<hash_t>& population, size_t r)
    {
        // This algorithm is cribbed from python's itertools page.
        size_t n = population.size();
        if (r > n)
        {
            throw std::invalid_argument("R cannot be greater than population size.");
        }

        std::vector<size_t> indices(r);
        for (size_t i = 0; i < r; ++i)
        {
            indices[i] = i;
        }

        std::vector<std::vector<hash_t> > results;
        std::vector<hash_t> result(r);

        for (size_t i = 0; i < r; ++i)
        {
            result[i] = population[indices[i]];
        }
        results.push_back(result);

        while (true)
        {
            int i = r - 1;
            for (; i >= 0; --i)
            {
                if (indices[i] != i + n - r)
                {
                    break;
                }
            }
            if (i < 0)
            {
                return results;
            }

            indices[i] += 1;
            for (size_t j = i + 1; j < r; ++j)
            {
                indices[j] = indices[j-1] + 1;
            }
            for (size_t j = 0; j < r; ++j)
            {
                result[j] = population[indices[j]];
            }
            results.push_back(result);
        }
    }

    std::vector<Permutation> Permutation::create(size_t number_of_blocks,
                                                 size_t different_bits)
    {
        if (number_of_blocks > Simhash::BITS)
        {
            std::stringstream message;
            message << "Number of blocks must not exceed " << sizeof(hash_t) * 8;
            throw std::invalid_argument(message.str());
        }

        if (number_of_blocks <= different_bits)
        {
            std::stringstream message;
            message << "Number of blocks (" << number_of_blocks
                    << ") must be greater than different_bits (" << different_bits
                    << ")";
            throw std::invalid_argument(message.str());
        }

        /* These are the blocks, in mask form. */
        std::vector<hash_t> blocks;
        for (size_t i = 0; i < number_of_blocks; ++i)
        {
            hash_t mask(0);
            size_t start = (   i    * Simhash::BITS) / number_of_blocks;
            size_t end   = ((i + 1) * Simhash::BITS) / number_of_blocks;
            for (size_t j = start; j < end; ++j)
            {
                mask |= (static_cast<hash_t>(1) << j);
            }
            blocks.push_back(mask);
        }

        /* This is the number of blocks in the leading prefix. */
        size_t count = static_cast<size_t>(number_of_blocks - different_bits);

        /* All the mask choices. */
        std::vector<Permutation> results;
        for (std::vector<hash_t>& choice : choose(blocks, count))
        {
            // Add the remaining masks -- those that were not part of choice
            for (hash_t block : blocks)
            {
                if (find(choice.begin(), choice.end(), block) == choice.end())
                {
                    choice.push_back(block);
                }
            }

            results.push_back(Permutation(different_bits, choice));
        }

        return results;
    }

    Permutation::Permutation(size_t different_bits, std::vector<hash_t>& masks)
        : forward_masks(masks)
        , reverse_masks()
        , offsets()
        , search_mask_(0)
    {
        int j(0), i(0), width(0); // counters

        // All of these are O(forward_masks)
        std::vector<size_t> widths;
        widths.reserve(forward_masks.size());
        reverse_masks.reserve(forward_masks.size());
        offsets.reserve(forward_masks.size());

        std::vector<hash_t>::iterator mask_it(forward_masks.begin());

        /* To more easily and reasonably-efficiently calculate the permutations
         * of each of the hashes we insert, and since each block is just
         * contiguous set bits, we will calculate the widths of each of these
         * blocks, and the offset of their rightmost bit. With this, we'll
         * generate net offsets between their positions in the unpermuted and
         * permuted forms, and simultaneously generate reverse masks */
        for(; mask_it != forward_masks.end(); ++mask_it)
        {
            hash_t mask = *mask_it;
            /* Find where the 1's start, and where they end. After this, `i` is
             * the position to the right of the rightmost set bit. `j` is the
             * position of the leftmost set bit. In `width`, we keep a running
             * tab of the widths of the bitmasks so far. */
            for (i = 0;          !((1UL << i) & mask); ++i) {}
            for (j = i; j < 64 && ((1UL << j) & mask); ++j) {}

            /* Just to prove that I'm sane, and in case that I'm ever running
             * circles around this logic in the future, consider:
             *
             *     63---53|52---42|41---32|31---21|20---10|09---00|
             *     |  A   |   B   |   C   |   D   |   E   |   F   |
             *
             *                       permuted to
             *     63---53|52---42|41---32|31---21|20---10|09---00|
             *     |  C   |   D   |   E   |   A   |   B   |   F   |
             *
             * The first loop, we'll have width = 0, and examining the mask for
             * C, we'll find that i = 31 and j = 41, so we find that its width
             * is 10. In the end, the bit in position 32 needs to move to be in
             * position 53. Width serves as an accumulator of the widths of the
             * blocks inserted into the permuted value, so we increment it by
             * the width of C (j-i) = 10. Now the end offset is 63 - width = 53,
             * and the original offset for that bit was (i+1) = 32, and we find
             * that we need an offset of 63 - width - i - 1 = 62 - width - i:
             *
             *    C: i = 31 | j = 41 | width = 0  | end = 53
             *       width += (j-i)          => 10
             *       offset = 62 - width - i => 21
             *
             *    D: i = 20 | j = 31 | width = 10 | end = 42
             *       width += (j-i)          => 21
             *       offset = 62 - width - i => 21 */
            width += (j - i);
            widths.push_back(j - i);

            int offset = 64 - width - i;
            offsets.push_back(offset);

            /* It's a trivial transformation, but we'll pre-compute our reverse
             * masks so that we don't have to compute for after the every time
             * we unpermute a number */
            if (offset > 0)
            {
                reverse_masks.push_back(mask <<  offset);
            }
            else
            {
                reverse_masks.push_back(mask >> -offset);
            }
        }

        /* Alright, we have to determine the low and high masks for this
         * particular table. If we are searching for up to /d/ differing bits,
         * then we should  include all but the last /d/ blocks in our mask.
         *
         * After this, width should hold the number of bits that are in all but
         * the last d blocks */
        std::vector<size_t>::iterator width_it(widths.begin());
        for (width = 0; different_bits < widths.size(); ++different_bits, ++width_it)
        {
            width += *width_it;
        }

        /* Set the first /width/ bits in the low mask to 1, and then shift it up
         * until it's a full 64-bit number. */
        for(i = 0    ; i < width; ++i) { search_mask_ = (search_mask_ << 1) | 1; }
        for(i = width; i < 64   ; ++i) { search_mask_ =  search_mask_ << 1;      }
    }

    hash_t Permutation::apply(hash_t hash) const
    {
        std::vector<hash_t>::const_iterator masks_it(forward_masks.begin());
        std::vector<int   >::const_iterator offset_it(     offsets.begin());

        hash_t result(0);
        for (; masks_it != forward_masks.end(); ++masks_it, ++offset_it)
        {
            if (*offset_it > 0)
            {
                result = result | ((hash & *masks_it) <<   *offset_it );
            }
            else
            {
                result = result | ((hash & *masks_it) >> -(*offset_it));
            }
        }
        return result;
    }

    hash_t Permutation::reverse(hash_t hash) const
    {
        std::vector<hash_t>::const_iterator masks_it(reverse_masks.begin());
        std::vector<int   >::const_iterator offset_it(     offsets.begin());

        hash_t result(0);
        for (; masks_it != reverse_masks.end(); ++masks_it, ++offset_it)
        {
            if (*offset_it > 0)
            {
                result = result | ((hash & *masks_it) >>   *offset_it );
            }
            else
            {
                result = result | ((hash & *masks_it) << -(*offset_it));
            }
        }
        return result;
    }

    hash_t Permutation::search_mask() const
    {
        return search_mask_;
    }
}

#include "simhash.h"
#include "permutation.h"

#include <algorithm>

size_t Simhash::num_differing_bits(Simhash::hash_t a, Simhash::hash_t b)
{
    size_t count(0);
    Simhash::hash_t n = a ^ b;
    while (n)
    {
        ++count;
        n = n & (n - 1);
    }
    return count;
}

Simhash::hash_t Simhash::compute(const std::vector<Simhash::hash_t>& hashes)
{
    // Initialize counts to 0
    std::vector<long> counts(Simhash::BITS, 0);

    // Count the number of 1's, 0's in each position of the hashes
    for (auto it = hashes.begin(); it != hashes.end(); ++it)
    {
        Simhash::hash_t hash = *it;
        for (size_t i = 0; i < BITS; ++i)
        {
            counts[i] += (hash & 1) ? 1 : -1;
            hash >>= 1;
        }
    }

    // Produce the result
    Simhash::hash_t result(0);
    for (size_t i = 0; i < BITS; ++i) {
        if (counts[i] > 0)
        {
            result |= (static_cast<Simhash::hash_t>(1) << i);
        }
    }
    return result;
}

/**
 * Find all near-matches in a set of hashes.
 *
 * This works by putting the provided hashes into a vector. Then, for each permutation,
 * apply the permutation and sort the permuted hashes. Then walk the hashes, finding each
 * unique prefix.
 *
 * For each unique prefix, consider all hashes sharing that prefix, adding matches with
 * the lower number first (to avoid duplication; suppose a < b -- we will only emit (a, b)
 * as a match, but (b, a) will not be emitted).
 */
Simhash::matches_t Simhash::find_all(
    std::unordered_set<Simhash::hash_t>& hashes,
    size_t number_of_blocks,
    size_t different_bits)
{
    std::vector<Simhash::hash_t> copy(hashes.begin(), hashes.end());
    Simhash::matches_t results;
    auto permutations = Simhash::Permutation::create(number_of_blocks, different_bits);
    for (Simhash::Permutation& permutation : permutations)
    {
        // Apply the permutation to the set of hashes and sort
        auto op = [permutation](Simhash::hash_t h) -> Simhash::hash_t {
            return permutation.apply(h);
        };
        std::transform(hashes.begin(), hashes.end(), copy.begin(), op);
        std::sort(copy.begin(), copy.end());

        // Walk through and find regions that have the same prefix subject to the mask
        Simhash::hash_t mask = permutation.search_mask();
        auto start = copy.begin();
        while (start != copy.end())
        {
            // Find the end of the range that starts with this prefix
            Simhash::hash_t prefix = (*start) & mask;
            std::vector<Simhash::hash_t>::iterator end = start;
            for (; end != copy.end() && (*end & mask) == prefix; ++end) { }

            // For all the hashes that are between start and end, consider them all
            for (auto a = start; a != end; ++a)
            {
                for (auto b = a + 1; b != end; ++b)
                {
                    if (Simhash::num_differing_bits(*a, *b) <= different_bits)
                    {
                        Simhash::hash_t a_raw = permutation.reverse(*a);
                        Simhash::hash_t b_raw = permutation.reverse(*b);
                        // Insert the result keyed on the smaller of the two
                        results.insert(
                            std::make_pair(
                                std::min(a_raw, b_raw),
                                std::max(a_raw, b_raw)));
                    }
                }
            }

            // Advance start to after the block
            start = end;
        }
    }

    return results;
}

