TEST(NumDifferingBitsTest, Basic)
{
    Simhash::hash_t a = 0xDEADBEEF;
    Simhash::hash_t b = 0xDEADBEAD;
    size_t expected = 2;
    EXPECT_EQ(expected, Simhash::num_differing_bits(a, b));
}

