    std::vector<Simhash::hash_t> hashes = {
        0xDEADBEEF, ~0xDEADBEEF
    };
    Simhash::hash_t expected = 0;
    EXPECT_EQ(expected, Simhash::compute(hashes));
}

TEST(SimhashTest, Basic)
